mapper.select:
select sum(total_account) from member_info
and reg_time >= STR_TO_DATE(CONCAT(#{inclusive_date},' 00:00:00'),'%Y-%m-%d %H:%i:%s') and reg_time <= STR_TO_DATE(CONCAT(#{inclusive_date},' 23:59:59'),'%Y-%m-%d %H:%i:%s')
and inviter_code = #{channelCode}

select count(id) total_registration from member_info
and reg_time >= STR_TO_DATE(CONCAT(#{inclusive_date},' 00:00:00'),'%Y-%m-%d %H:%i:%s') and reg_time <= STR_TO_DATE(CONCAT(#{inclusive_date},' 23:59:59'),'%Y-%m-%d %H:%i:%s')
and inviter_code = #{channelCode}

select ifnull( SUM( lvp.total_ticket ), 0.0 ) total_gift from ${dbLive}.live_video_prop lvp where lvp.to_user_id > 0
and lvp.create_date = #{inclusive_date}
and lvp.p_user_id in ( select mi.id from ${dbMain}.member_info mi where mi.inviter_code = #{channelCode} )

SELECT ifnull(count( distinct a.member_id), 0) dailyRechargeCount, ifnull(sum( distinct a.recharge_money), 0) totalRecharge FROM ( SELECT p.member_id member_id, p.recharge_money FROM member_recharge_log p WHERE p.status = 3
and p.update_time >= STR_TO_DATE(CONCAT(#{req.inclusive_date},' 00:00:00'),'%Y-%m-%d %H:%i:%s') and p.update_time <= STR_TO_DATE(CONCAT(#{req.inclusive_date},' 23:59:59'),'%Y-%m-%d %H:%i:%s')
) as a inner join member_info as mi on mi.id = a.member_id where mi.inviter_code = #{req.channelCode}
